6	import { Emitter } from '../../../util/vs/base/common/event';
7	import { Disposable } from '../../../util/vs/base/common/lifecycle';
8	import { IAuthenticationService } from '../../authentication/common/authentication';
9	import { ILogService } from '../../log/common/logService';
10	import { IHeaders } from '../../networking/common/fetcherService';
11	import { CopilotUserQuotaInfo, IChatQuota, IChatQuotaService, QuotaSnapshots } from './chatQuotaService';
12	
13	export class ChatQuotaService extends Disposable implements IChatQuotaService {
14		declare readonly _serviceBrand: undefined;
15	
16		private _quotaInfo: IChatQuota | undefined;
17		private _rateLimitInfo: { session: IChatQuota | undefined; weekly: IChatQuota | undefined };
18		private readonly _turnCredits = new Map<string, number>();
19	
20		private readonly _onDidChange = this._register(new Emitter<void>());
21		readonly onDidChange = this._onDidChange.event;
22	
23		constructor(
24			@IAuthenticationService private readonly _authService: IAuthenticationService,
25			@ILogService private readonly _logService: ILogService,
26		) {
27			super();
28			this._rateLimitInfo = { session: undefined, weekly: undefined };
29			this._register(this._authService.onDidAuthenticationChange(() => {
30				this._processUserInfoQuotaSnapshot(this._authService.copilotToken?.quotaInfo);
31			}));
32		}
33	
34		get quotaInfo(): IChatQuota | undefined {
35			return this._quotaInfo;
36		}
37	
38		get rateLimitInfo(): { readonly session: IChatQuota | undefined; readonly weekly: IChatQuota | undefined } {
39			return this._rateLimitInfo;
40		}
41	
42		get quotaExhausted(): boolean {
43			if (!this._quotaInfo) {
44				return false;
45			}
46			return this._quotaInfo.percentRemaining <= 0 && !this._quotaInfo.additionalUsageEnabled && !this._quotaInfo.unlimited;
47		}
48	
49		get additionalUsageEnabled(): boolean {
50			if (!this._quotaInfo) {
51				return false;
52			}
53			return this._quotaInfo.additionalUsageEnabled;
54		}
55	
56		getCreditsForTurn(turnId: string): number | undefined {
57			return this._turnCredits.get(turnId);
58		}
59	
60		setLastCopilotUsage(totalNanoAiu: number, turnId: string): void {
61			// Convert nano-AIUs to AIC credits: 1 AIC = 1_000_000_000 nano-AIU
62			const aic = totalNanoAiu / 1_000_000_000;
63			if (aic > 0) {
64				this._turnCredits.set(turnId, (this._turnCredits.get(turnId) ?? 0) + aic);
65			}
66		}
67	
68		resetTurnCredits(turnId: string): void {
69			this._turnCredits.delete(turnId);
70		}
71	
72		clearQuota(): void {
73			this._quotaInfo = undefined;
74		}
75	
76		processQuotaHeaders(headers: IHeaders): void {
77			const quotaHeader = this._authService.copilotToken?.isFreeUser ? headers.get('x-quota-snapshot-chat') : headers.get('x-quota-snapshot-premium_models') || headers.get('x-quota-snapshot-premium_interactions');
78			if (!quotaHeader) {
79				return;
80			}
81			const quotaInfo = this._processHeaderValue(quotaHeader);
82			if (!quotaInfo) {
83				return;
84			}
85			this._quotaInfo = quotaInfo;
86			this._logService.trace(`[ChatQuota] processQuotaHeaders: ${JSON.stringify(quotaInfo)}`);
87			const sessionRateLimitHeader = headers.get('x-usage-ratelimit-session');
88			const weeklyRateLimitHeader = headers.get('x-usage-ratelimit-weekly');
89			this._rateLimitInfo.session = sessionRateLimitHeader ? this._processHeaderValue(sessionRateLimitHeader) : undefined;
90			this._rateLimitInfo.weekly = weeklyRateLimitHeader ? this._processHeaderValue(weeklyRateLimitHeader) : undefined;
91			this._onDidChange.fire();
92		}
93	
94		processQuotaSnapshots(snapshots: QuotaSnapshots): void {
95			const snapshot = this._authService.copilotToken?.isFreeUser
96				? snapshots['chat']
97				: snapshots['premium_models'] ?? snapshots['premium_interactions'];
98			if (!snapshot) {
99				return;
100			}
101	
102			try {
103				const entitlement = parseInt(snapshot.entitlement, 10);
104				const resetDate = snapshot.reset_date ? new Date(snapshot.reset_date) : (() => { const d = new Date(); d.setMonth(d.getMonth() + 1); return d; })();
105	
106				this._quotaInfo = {
107					quota: entitlement,
108					unlimited: entitlement === -1,
109					percentRemaining: snapshot.percent_remaining,
110					additionalUsageUsed: snapshot.overage_count,
111					additionalUsageEnabled: snapshot.overage_permitted,
112					resetDate,
113				};
114				this._logService.trace(`[ChatQuota] processQuotaSnapshots: ${JSON.stringify(this._quotaInfo)}`);
115				this._onDidChange.fire();
116			} catch (error) {
117				console.error('Failed to process quota snapshots', error);
118			}
119		}
120	
121		private _processHeaderValue(header: string): IChatQuota | undefined {
122			try {
123				// Parse URL encoded string into key-value pairs
124				const params = new URLSearchParams(header);
125	
126				// Extract values with fallbacks to ensure type safety
127				const entitlement = parseInt(params.get('ent') || '0', 10);
128				const additionalUsageUsed = parseFloat(params.get('ov') || '0.0');
129				const additionalUsageEnabled = params.get('ovPerm') === 'true';
130				const percentRemaining = parseFloat(params.get('rem') || '0.0');
131				const resetDateString = params.get('rst');
132	
133				let resetDate: Date;
134				if (resetDateString) {
135					resetDate = new Date(resetDateString);
136				} else {
137					// Default to one month from now if not provided
138					resetDate = new Date();
139					resetDate.setMonth(resetDate.getMonth() + 1);
140				}
141	
142				return {
143					quota: entitlement,
144					unlimited: entitlement === -1,
145					percentRemaining,
146					additionalUsageUsed,
147					additionalUsageEnabled,
148					resetDate,
149				};
150			} catch (error) {
151				console.error('Failed to parse quota header', error);
152				return undefined;
153			}
154		}
155	
156		private _processUserInfoQuotaSnapshot(quotaInfo: CopilotUserQuotaInfo | undefined) {
157			if (!quotaInfo || !quotaInfo.quota_snapshots || !quotaInfo.quota_reset_date) {
158				return;
159			}
160			const snapshot = this._authService.copilotToken?.isFreeUser
161				? quotaInfo.quota_snapshots.chat
162				: quotaInfo.quota_snapshots.premium_interactions;
163			this._quotaInfo = {
164				unlimited: snapshot.unlimited,
165				additionalUsageEnabled: snapshot.overage_permitted,
166				additionalUsageUsed: snapshot.overage_count,
167				quota: snapshot.entitlement,
168				resetDate: new Date(quotaInfo.quota_reset_date),
169				percentRemaining: snapshot.percent_remaining,
170			};
171			this._logService.trace(`[ChatQuota] processUserInfoQuotaSnapshot: ${JSON.stringify(this._quotaInfo)}`);
172			this._onDidChange.fire();
173		}
174	}
